const customNodes=basicSchema.spec.nodes.update('paragraph',nodeSpecs.paragraph).update('heading',nodeSpecs.heading).update('blockquote',nodeSpecs.blockquote).append({horizontal_rule:nodeSpecs.horizontal_rule,image:nodeSpecs.image,button:nodeSpecs.button,divider:nodeSpecs.divider,spacer:nodeSpecs.spacer,callout:nodeSpecs.callout,columns:nodeSpecs.columns,column:nodeSpecs.column,table:nodeSpecs.table,table_row:nodeSpecs.table_row,table_cell:nodeSpecs.table_cell,embed:nodeSpecs.embed,media:nodeSpecs.media,email_header:nodeSpecs.email_header,email_footer:nodeSpecs.email_footer});const listNodes=addListNodes(customNodes,'paragraph block*','block');const schema=new Schema({nodes:listNodes,marks});const editorPlugins=()=>[history(),keymap({'Mod-b':toggleMark(schema.marks.strong),'Mod-i':toggleMark(schema.marks.em),'Mod-z':undo,'Mod-y':redo,'Mod-Shift-z':redo}),keymap(baseKeymap)];
